/**
 * Clinical Demo Seed — بيانات سريرية تجريبية
 *
 * One coherent hospital day. The cohort is deliberately small and deeply
 * linked rather than large and shallow: every patient here has a story that
 * crosses modules, so opening any screen shows real consequences of what
 * happened on another.
 *
 *   pt-01  Khalid Al-Otaibi   ED chest pain → admitted CCU → troponin rising
 *   pt-02  Maryam Al-Ghamdi   Post-op day 1, laparoscopic cholecystectomy
 *   pt-03  Fatima Al-Harbi    Diabetic outpatient, renal impairment, dose alerts
 *   pt-04  Noura Al-Qahtani   Maternity, term, for elective section
 *   pt-05  Yousef Al-Dosari   Paediatric asthma, ED short stay
 *   pt-06  Abdullah Al-Shehri ICU, ventilated, sepsis
 *   pt-07  Sara Al-Mutairi    Day case, cataract, discharged
 *   pt-08  Ibrahim Al-Zahrani Orthopaedic, awaiting theatre
 *   pt-09  Hessa Al-Subaie    Oncology day unit, chemotherapy
 *   pt-10  Majed Al-Rashid    ED waiting, ankle injury, fast-track
 *   pt-11  Layla Al-Anazi     Telehealth follow-up, dermatology
 *   pt-12  Turki Al-Malki     ED triage 2, breathing difficulty
 *   pt-13  Reem Al-Faisal     Outpatient clinic, thyroid
 *   pt-14  Saud Al-Amri       Discharged yesterday, claim in progress
 *
 * All IDs are stable so cross-module links never dangle.
 */

import type { Database } from "@/domain/types";

type T<K extends keyof Database["public"]["Tables"]> = Database["public"]["Tables"][K]["Row"];

const W = "demo";

/** Date helpers — everything is relative so the demo never looks stale. */
const d = (daysAgo: number) => new Date(Date.now() - daysAgo * 86_400_000).toISOString().slice(0, 10);
const ts = (daysAgo: number) => new Date(Date.now() - daysAgo * 86_400_000).toISOString();
const hrs = (hoursAgo: number) => new Date(Date.now() - hoursAgo * 3_600_000).toISOString();
const mins = (minutesAgo: number) => new Date(Date.now() - minutesAgo * 60_000).toISOString();
/** Forward-dated, for scheduled things. */
const inHrs = (hoursAhead: number) => new Date(Date.now() + hoursAhead * 3_600_000).toISOString();
const inDays = (daysAhead: number) => new Date(Date.now() + daysAhead * 86_400_000).toISOString();
/** A fixed birth date `years` ago, so ages stay stable within a session. */
const dob = (years: number, month = 5, day = 12) =>
  `${new Date().getFullYear() - years}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;

