/**
 * Beds are generated so the occupancy board has realistic volume, then the
 * ones that matter clinically are overridden below. A hand-written list of
 * 52 beds would be noise; the overrides are the part worth reading.
 */
function generateBeds(): T<"beds">[] {
  const spec: [wardId: string, wardName: string, count: number, type: T<"beds">["bed_type"], prefix: string][] = [
    ["wd-01", "Coronary Care Unit", 8, "icu", "CCU"],
    ["wd-02", "Surgical Ward A", 12, "standard", "SA"],
    ["wd-03", "Intensive Care Unit", 10, "icu", "ICU"],
    ["wd-04", "Maternity Ward", 10, "standard", "MAT"],
    ["wd-05", "Paediatric Ward", 8, "paediatric", "PD"],
    ["wd-06", "Isolation Unit", 4, "isolation", "ISO"],
  ];
  const beds: T<"beds">[] = [];
  for (const [wardId, wardName, count, type, prefix] of spec) {
    for (let i = 1; i <= count; i++) {
      // A deterministic spread: roughly 60% occupied, some cleaning, some free.
      const cycle = i % 5;
      const status: T<"beds">["status"] =
        cycle === 0 ? "cleaning" : cycle === 4 ? "available" : "occupied";
      beds.push({
        id: `bed-${prefix}-${String(i).padStart(2, "0")}`,
        workspace_id: W, ward_id: wardId, ward_name: wardName,
        room: `${prefix}-${Math.ceil(i / 2)}`, label: `${prefix}-${String(i).padStart(2, "0")}`,
        bed_type: type, status,
        current_encounter_id: null,
        current_patient_name: status === "occupied" ? "—" : null,
        occupied_since: status === "occupied" ? hrs(6 + (i % 40)) : null,
        reserved_until: null,
        has_oxygen: type === "icu" || type === "isolation" || i % 3 === 0,
        has_monitor: type === "icu",
        metadata: {}, created_at: ts(400), updated_at: hrs(i % 12),
      });
    }
  }
  return beds;
}

const beds = generateBeds();

/** The beds our cohort actually occupies, patched onto the generated grid. */
const BED_ASSIGNMENTS: [bedId: string, encounterId: string, patientName: string, hoursOccupied: number][] = [
  ["bed-CCU-01", "enc-01", "Khalid Al-Otaibi", 9],
  ["bed-SA-01", "enc-02", "Maryam Al-Ghamdi", 28],
  ["bed-ICU-02", "enc-06", "Abdullah Al-Shehri", 76],
  ["bed-MAT-03", "enc-04", "Noura Al-Qahtani", 14],
  ["bed-PD-02", "enc-05", "Yousef Al-Dosari", 5],
  ["bed-SA-06", "enc-08", "Ibrahim Al-Zahrani", 20],
];

for (const [bedId, encId, name, hoursOccupied] of BED_ASSIGNMENTS) {
  const bed = beds.find((b) => b.id === bedId);
  if (bed) {
    bed.status = "occupied";
    bed.current_encounter_id = encId;
    bed.current_patient_name = name;
    bed.occupied_since = hrs(hoursOccupied);
  }
}

// A blocked bay, so the board shows why capacity is short.
const isoBed = beds.find((b) => b.id === "bed-ISO-03");
if (isoBed) {
  isoBed.status = "blocked";
  isoBed.current_encounter_id = null;
  isoBed.current_patient_name = null;
  isoBed.occupied_since = null;
  isoBed.metadata = { blocked_reason: "Awaiting HEPA filter replacement — BIOM-WO-0231" };
}

export const DEMO_BEDS = beds;

